<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api, withBasePath, activeStatuses, dateLabel, modeLabels, runLabels, stageLabels } from '../api';
import { workflowStage, objectScope, isReportRebuild, runTitle, runStages } from '../run-presentation';
import { workspace, currentBoard, loadWorkspace } from '../workspace';
import EmptyState from '../components/EmptyState.vue';
import StatusBadge from '../components/StatusBadge.vue';
import AppIcon from '../components/AppIcon.vue';
const route=useRoute();const router=useRouter();
const rules=ref([]), runs=ref([]), profiles=ref([]), activeRun=ref(null), events=ref([]);
const loading=ref(false), busy=ref(''), error=ref(''), streamState=ref(''), concurrencyError=ref('');
const mode=ref('program'), selectedRules=ref([]), concurrency=ref(2), profileId=ref(''), objects=ref(''), query=ref('');
let boardGeneration=0, runGeneration=0, actionGeneration=0, stream=null, timer=null, refreshing=null;
const availableRules=computed(()=>rules.value.filter(rule=>mode.value!=='program'||rule.mode==='program'));
const displayedRules=computed(()=>availableRules.value.filter(rule=>`${rule.id} ${rule.title}`.toLowerCase().includes(query.value.toLowerCase())));
const inFlight=computed(()=>runs.value.find(run=>activeStatuses.has(run.status)));
const active=computed(()=>activeRun.value&&activeStatuses.has(activeRun.value.status));
const needModel=computed(()=>mode.value==='review');
const selectedCount=computed(()=>selectedRules.value.length);
const progressCount=computed(()=>activeRun.value?.progress?.completed ?? activeRun.value?.completed ?? 0);
const progressTotal=computed(()=>activeRun.value?.progress?.total ?? activeRun.value?.total ?? 0);
const errorText=computed(()=>{const value=activeRun.value?.error||activeRun.value?.errors;if(Array.isArray(value))return value.map(x=>typeof x==='string'?x:JSON.stringify(x)).join('\n');return typeof value==='string'?value:value?JSON.stringify(value):'';});
const tone=status=>status==='completed'?'success':status==='failed'?'danger':status==='running'?'info':status==='stopping'?'warning':'neutral';
const stages=computed(()=>runStages(activeRun.value));
const requestedObjects=computed(()=>mode.value==='materials'?[]:objects.value.split(/[，,\s]+/).map(x=>x.trim()).filter(Boolean));
const selectedProfile=computed(()=>profiles.value.find(p=>p.id===profileId.value));
watch(mode,()=>{selectedRules.value=route.query.rule&&availableRules.value.some(r=>r.id===route.query.rule)?[String(route.query.rule)]:availableRules.value.map(r=>r.id);});
function applyScope(){if(['materials','program','review'].includes(route.query.mode))mode.value=route.query.mode;if(route.query.object)objects.value=String(route.query.object);if(route.query.rule&&availableRules.value.some(r=>r.id===route.query.rule))selectedRules.value=[String(route.query.rule)];}
watch(()=>[route.query.mode,route.query.rule,route.query.object],applyScope);
function selectAll(){selectedRules.value=availableRules.value.map(r=>r.id);}
function clearSelection(){selectedRules.value=[];}
function onFormInvalid(event){
  const field=event.target;
  if(field.id!=='run-concurrency')return;
  concurrencyError.value=field.validationMessage||'对象并发数需为 1–8 之间的整数。';
  const section=field.closest('details');if(section)section.open=true;
}
function stopWatching(){if(stream)stream.close();stream=null;clearInterval(timer);timer=null;streamState.value='';}
async function refreshRun(){
  const id=activeRun.value?.id, token=boardGeneration, key=token+':'+id;
  if(!id||refreshing===key)return;
  refreshing=key;
  const current=()=>boardGeneration===token&&activeRun.value?.id===id;
  try{const result=await api.run(id);if(!current())return;activeRun.value=result.run||result;if(Array.isArray(result.events))events.value=result.events;const index=runs.value.findIndex(r=>r.id===id);if(index>=0)runs.value[index]=activeRun.value;if(!activeStatuses.has(activeRun.value.status)){stopWatching();await loadWorkspace();}}
  catch(e){if(current())error.value=e.message;}
  finally{if(refreshing===key)refreshing=null;}
}
function followRun(id){stopWatching();if(!activeStatuses.has(activeRun.value?.status))return;streamState.value='connecting';stream=new EventSource(withBasePath(`/api/runs/${encodeURIComponent(id)}/events`));stream.onopen=()=>{streamState.value='live';};stream.onerror=()=>{streamState.value='reconnecting';};const receive=event=>{try{const row=JSON.parse(event.data);if(row.seq&&!events.value.some(e=>e.seq===row.seq))events.value=[...events.value,row].slice(-200);}catch{/* Refresh remains authoritative. */}refreshRun();};stream.onmessage=receive;for(const name of ['queued','progress','stage','status','completed','failed','stopped','event','log','update','run'])stream.addEventListener(name,receive);timer=setInterval(refreshRun,3000);}
async function showRun(id){const token=++runGeneration;stopWatching();activeRun.value=null;events.value=[];if(!id)return;try{const value=await api.run(id);if(token!==runGeneration)return;activeRun.value=value.run||value;events.value=value.events||[];followRun(activeRun.value.id);}catch(e){if(token===runGeneration)error.value=e.message;}}
async function load(){const id=workspace.boardId;const token=++boardGeneration;++runGeneration;++actionGeneration;refreshing=null;busy.value='';stopWatching();runs.value=[];activeRun.value=null;events.value=[];error.value='';if(!id)return;loading.value=true;try{const [rs,rr,pp]=await Promise.all([api.rules(),api.runs(id),api.profiles()]);if(token!==boardGeneration)return;rules.value=(rs.rules||[]).map(r=>({...r,id:r.id||r.rule_id,mode:r.mode==='agent'?'review':r.mode}));runs.value=rr.runs||[];profiles.value=pp.profiles||[];profileId.value=pp.default_profile_id||profiles.value[0]?.id||'';selectedRules.value=availableRules.value.map(r=>r.id);applyScope();const preferred=String(route.query.run||'');const current=runs.value.find(r=>r.id===preferred)||inFlight.value||runs.value[0];if(current)await showRun(current.id);}catch(e){if(token===boardGeneration)error.value=e.message;}finally{if(token===boardGeneration)loading.value=false;}}
watch(()=>workspace.boardId,load,{immediate:true});
watch(()=>route.query.run,id=>{if(id&&id!==activeRun.value?.id)showRun(String(id));});
function chooseRun(run){router.replace({path:'/runs',query:{board:workspace.boardId,run:run.id}});}
async function start(){
  if(mode.value!=='materials'&&!selectedRules.value.length){error.value='请至少选择一个检查项。';return;}
  const board=workspace.boardId, token=boardGeneration, task=++actionGeneration;
  const current=()=>workspace.boardId===board&&boardGeneration===token&&actionGeneration===task;
  busy.value='start';error.value='';
  try{
    const result=await api.createRun(board,{mode:mode.value,rule_ids:mode.value==='materials'?[]:selectedRules.value,objects:requestedObjects.value,concurrency:Number(concurrency.value),profile_id:profileId.value||null,resume:false});
    await loadWorkspace();if(!current())return;
    const run=result.run||result;runs.value=[run,...runs.value];await showRun(run.id);if(!current())return;
    router.replace({path:'/runs',query:{board,run:run.id}});
  }catch(e){if(current())error.value=e.message;}finally{if(current())busy.value='';}
}
async function act(action){
  if(!activeRun.value)return;
  const board=workspace.boardId, token=boardGeneration, task=++actionGeneration, id=activeRun.value.id;
  const current=()=>workspace.boardId===board&&boardGeneration===token&&actionGeneration===task;
  busy.value=action;error.value='';
  try{
    const result=await(action==='stop'?api.stopRun(id):api.resumeRun(id));if(!current())return;
    const run=result.run||result;
    if(action==='resume'&&run.id){runs.value=[run,...runs.value];await showRun(run.id);if(current())router.replace({path:'/runs',query:{board,run:run.id}});}
    else if(activeRun.value?.id===id)await refreshRun();
  }catch(e){if(current())error.value=e.message;}finally{if(current())busy.value='';}
}
function eventText(event){const data=event.data||event.payload||event;return data.message||data.detail||(data.stage?stageLabels[data.stage]||data.stage:'')||(event.type?stageLabels[event.type]||event.type:JSON.stringify(data));}
onBeforeUnmount(()=>{boardGeneration++;runGeneration++;actionGeneration++;stopWatching();});
</script>
<template>
  <EmptyState v-if="!workspace.boardId&&!workspace.loading" title="先选择一个项目" description="选择板卡后，可以配置评审范围并追踪后台任务。"><router-link class="button primary" to="/">前往项目</router-link></EmptyState>
  <section v-else class="runs-page">
    <div class="page-heading"><div><div class="eyebrow">REVIEW OPERATIONS</div><h1>运行任务</h1><p>{{ currentBoard?.name }} · 配置检查范围，跟踪每次执行和交付。</p></div><router-link class="button" :to="{path:'/materials',query:{board:workspace.boardId}}"><AppIcon name="file" :size="16" />查看材料</router-link></div>
    <div v-if="error" class="notice error" role="alert">{{ error }}</div>
    <div v-if="loading" class="loading-state">正在加载检查范围与任务</div>
    <div v-else class="run-layout">
      <form class="section-card run-settings" @submit.prevent="start" @invalid.capture="onFormInvalid"><div class="section-heading"><h2><AppIcon name="play" :size="17" />新建运行</h2><span>配置本次检查</span></div>
        <fieldset class="run-form-fields" :disabled="!!busy"><fieldset class="mode-options"><legend>执行模式</legend><label v-for="(label,key) in modeLabels" :key="key" :class="{selected:mode===key}"><input type="radio" v-model="mode" :value="key" name="run-mode" /><span>{{ label }}<small>{{ key==='materials'?'核对材料与连接事实':key==='program'?'执行可重复的程序规则':'通过模型分析对象与证据' }}</small></span><AppIcon v-if="mode===key" name="check-circle" :size="17" /></label></fieldset>
        <div v-if="needModel&&!profiles.length" class="notice warning">尚未配置模型服务。<router-link to="/models">前往模型设置</router-link></div>
        <template v-if="mode!=='materials'"><div class="section-heading rule-heading"><h3>检查范围 <span class="rule-count">{{ selectedCount }} 项</span></h3><div class="actions"><button class="table-action" type="button" @click="selectAll">全选</button><button class="table-action" type="button" @click="clearSelection">清空</button></div></div><div class="rule-search"><AppIcon name="search" :size="16" /><label class="sr-only" for="rule-search">搜索检查项</label><input id="rule-search" class="search-input" v-model="query" placeholder="搜索检查项或编号" /></div><div class="rule-options"><label v-for="rule in displayedRules" :key="rule.id" class="rule-option"><input type="checkbox" v-model="selectedRules" :value="rule.id" /><span><strong>{{ rule.id }}</strong>{{ rule.title }}</span><small>{{ rule.mode==='program'?'程序':'模型' }}</small></label><p v-if="!displayedRules.length" class="small-copy muted">没有匹配的检查项。</p></div>
          <div class="field objects-field"><label for="run-objects">对象范围</label><input id="run-objects" v-model="objects" placeholder="全部适用对象，或填写 R1, R2" aria-describedby="run-objects-help" /><span id="run-objects-help" class="help">留空检查全部适用对象；指定对象须属于所选检查项。</span></div>
          <div class="field model-picker"><label for="run-profile">模型配置</label><select id="run-profile" v-model="profileId"><option value="">{{ needModel?'请选择模型配置':'不使用模型配置' }}</option><option v-for="profile in profiles" :key="profile.id" :value="profile.id">{{ profile.name || profile.model }} · {{ profile.model }}</option></select><span class="help">{{ needModel?'本次深审使用所选模型读取材料并完成分析。':'电气判定由程序完成；选择模型可用于生成报告文案。' }}</span></div>
        </template>
        <details class="run-advanced"><summary>高级设置<AppIcon name="chevron-down" :size="14" /></summary><div class="field"><label for="run-concurrency">对象并发数</label><input id="run-concurrency" v-model="concurrency" type="number" min="1" max="8" required :aria-invalid="concurrencyError?true:undefined" :aria-describedby="concurrencyError?'run-concurrency-help run-concurrency-error':'run-concurrency-help'" @input="concurrencyError=''" /><span id="run-concurrency-help" class="help">同一时间执行的对象数量，范围为 1–8。</span><span v-if="concurrencyError" id="run-concurrency-error" class="field-error" role="alert">{{ concurrencyError }}</span></div></details>
        <div class="run-scope-preview" aria-label="本次运行范围"><span>本次运行</span><dl><div><dt>执行方式</dt><dd>{{ modeLabels[mode] }}</dd></div><div v-if="mode!=='materials'"><dt>检查项</dt><dd>{{ selectedCount }} 项</dd></div><div><dt>对象范围</dt><dd>{{ mode==='materials'?'材料准备':requestedObjects.length?requestedObjects.join('、'):'全部适用对象' }}</dd></div><div v-if="mode!=='materials'"><dt>模型</dt><dd>{{ selectedProfile?.name||selectedProfile?.model||'未选择' }}</dd></div></dl></div>
        <div v-if="inFlight" class="notice">本项目有任务{{ runLabels[inFlight.status] || '运行中' }}，完成或停止后可以创建新运行。</div><button class="button primary run-start" :disabled="!!busy||!!inFlight||(needModel&&!profileId)||(mode!=='materials'&&!selectedCount)"><AppIcon name="play" :size="16" />{{ busy==='start'?'正在创建任务…':mode==='materials'?'开始材料检查':'开始评审' }}</button></fieldset><p class="inline-note">任务在服务端后台执行，刷新或关闭页面后仍可追踪。</p>
      </form>
      <div class="run-monitor"><div v-if="!activeRun" class="section-card"><EmptyState title="准备开始一次检查" description="选择执行模式与检查范围。任务创建后，这里将显示真实阶段、事件和结果。" /></div><div v-else class="section-card run-detail-card"><div class="section-heading"><h2>运行详情</h2><StatusBadge :tone="tone(activeRun.status)">{{ runLabels[activeRun.status] || activeRun.status }}</StatusBadge></div>
        <div class="run-ident"><strong>{{ runTitle(activeRun) }}</strong><span class="mono">{{ activeRun.id?.slice(0,12) }}</span></div>
        <div v-if="isReportRebuild(activeRun)" class="notice rebuild-note"><AppIcon name="layers" :size="17" /><span>复用原评审结果重新生成报告，本次模型请求 <strong>{{ activeRun.model_request_count ?? activeRun.summary?.model_request_count ?? 0 }}</strong> 次。</span></div>
        <div class="current-stage" :class="{'stage-completed':activeRun.status==='completed'}"><div><span>{{ activeRun.status==='completed'?'交付状态':'当前阶段' }}</span><small v-if="progressTotal>0">{{ progressCount }} / {{ progressTotal }} 阶段</small><small v-else-if="active">正在确定阶段范围</small></div><strong>{{ workflowStage(activeRun.stage) || (activeRun.status==='queued'?'等待调度':'—') }}</strong><progress v-if="progressTotal>0" :value="progressCount" :max="progressTotal" :aria-label="`流程进度 ${progressCount}/${progressTotal} 阶段`"></progress></div>
        <ol class="run-stage-track" aria-label="执行阶段"><li v-for="(stage,index) in stages" :key="stage" :class="{current:workflowStage(activeRun.stage)===stage,done:activeRun.status==='completed'}"><span>{{ activeRun.status==='completed'?'✓':index+1 }}</span>{{ stage }}</li></ol>
        <dl class="metadata-list run-metadata"><div><dt>开始时间</dt><dd>{{ dateLabel(activeRun.started_at||activeRun.created_at) }}</dd></div><div v-if="activeRun.finished_at"><dt>结束时间</dt><dd>{{ dateLabel(activeRun.finished_at) }}</dd></div><div><dt>检查范围</dt><dd>{{ (activeRun.rule_ids||[]).join('、') || (activeRun.mode==='materials'?'材料准备':'全部适用规则') }}</dd></div><div><dt>对象范围</dt><dd>{{ objectScope(activeRun) }}</dd></div><div v-if="activeRun.parent_id||activeRun.report_rebuild_of"><dt>{{ isReportRebuild(activeRun)?'原评审批次':'续跑来源' }}</dt><dd class="mono">{{ (activeRun.report_rebuild_of||activeRun.parent_id).slice(0,12) }}</dd></div></dl>
        <div v-if="errorText" class="notice error run-error" role="alert">{{ errorText }}</div><div v-if="activeRun.status==='completed'" class="notice success run-success"><AppIcon name="check-circle" :size="17" />执行已完成，工程判定请查看报告中的对象结论。</div><div class="actions run-actions"><button v-if="active" class="button danger" :disabled="!!busy||activeRun.status==='stopping'" @click="act('stop')">{{ busy==='stop'||activeRun.status==='stopping'?'正在停止…':'停止运行' }}</button><button v-if="['stopped','interrupted','failed'].includes(activeRun.status)" class="button" :disabled="!!busy||!!inFlight" @click="act('resume')">{{ busy==='resume'?'创建续跑…':'从有效结果续跑' }}</button><router-link v-if="activeRun.report_url||activeRun.report_dir" class="button primary" :to="{path:'/reports',query:{board:workspace.boardId,run:activeRun.id}}">打开评审报告<AppIcon name="arrow-right" :size="16" /></router-link><button class="button ghost" :disabled="!!busy" @click="refreshRun"><AppIcon name="refresh" :size="15" />刷新状态</button></div>
      </div>
      <div v-if="activeRun" class="section-card events-card"><div class="section-heading"><h2>运行事件</h2><span v-if="active" role="status"><span class="live-dot"></span>{{ streamState==='live'?'实时连接':streamState==='reconnecting'?'重连中 · 自动刷新':'正在连接事件流' }}</span><span v-else>{{ events.length }} 条已记录事件</span></div><ol v-if="events.length" class="event-list"><li v-for="(event,index) in events.slice(-50).reverse()" :key="event.seq||index"><time>{{ dateLabel(event.created_at||event.ts) }}</time><span>{{ eventText(event) }}</span></li></ol><p v-else class="small-copy muted">任务开始后会在这里记录阶段和交付事件。</p></div></div>
    </div>
    <div v-if="runs.length" class="section-card history-table"><div class="section-heading"><h2>运行记录</h2><span>{{ runs.length }} 个批次</span></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>批次 / 执行方式</th><th>检查范围</th><th>创建时间</th><th>状态</th><th class="history-actions">操作</th></tr></thead><tbody><tr v-for="run in runs" :key="run.id" :class="{'selected-run':activeRun?.id===run.id}"><td><strong class="mono">{{ run.id?.slice(0,12) }}</strong><small class="run-history-kind">{{ runTitle(run) }}</small></td><td class="run-history-scope"><span>{{ (run.rule_ids||[]).length }} 项检查</span><small>{{ objectScope(run) }}</small></td><td class="run-history-date">{{ dateLabel(run.created_at) }}</td><td><StatusBadge :tone="tone(run.status)">{{ runLabels[run.status]||run.status }}</StatusBadge></td><td class="history-actions"><button class="table-action" @click="chooseRun(run)">查看运行</button></td></tr></tbody></table></div></div>
  </section>
</template>
<style scoped>
